python -c $'import csv
from pymatgen.io.vasp import Poscar
ids={"c005","c030","c038","c042","c056","c058","c088"}
for r in csv.DictReader(open("nlo_pool.csv")):
 if r["candidate_id"] in ids:
  s=Poscar.from_str(r["poscar"]).structure
  print("\n"+r["candidate_id"], " ".join(f"{x.specie.symbol}@({x.frac_coords[0]:.3f},{x.frac_coords[1]:.3f},{x.frac_coords[2]:.3f})" for x in s))'

